 result['checks'].append({'name':name,'passed':bool(ok),'detail':detail});(OUT/'room-templates.json').write_text(json.dumps(result,indent=2)+'\n');print('PASS'if ok else'FAIL',name,detail or '',flush=True);assert ok,name
