   g.locator('#view').focus();g.keyboard.press('Space');air=g.evaluate('''async()=>{const g=adventure.game;for(let i=0;i<24;i++)g.update(1/120,{x:0,z:0,run:false});const live=g.player.y,snapshot=g.snapshot();await g.session.save();const id=g.session.current.id;await g.session.open(id);return{live,saved:snapshot.player.y,restored:g.player.y,inside:g.data.inside.id===entry.id}}''');check(kind+' upper-floor jump saves/reloads on the correct upper floor',air['live']>3.4 and 2.99<air['saved']<3.01 and 2.99<air['restored']<3.01 and air['inside'],air)
   edit=g.evaluate('''()=>{const g=adventure.game,p=g.objects.find(p=>p.id==='bed');g.beginPlacement(p.asset,p);g.placementAnchor={x:p.x+.2,z:p.z};g.updateGhost();const problem=g.placementProblem(g.pending,g.ghost);if(!problem)g.confirmEdit();else g.cancelEdit();g.cameraYaw=.5;g.cameraPosition.set(0,0,0);g.cameraUpdate(1/60);g.renderScene();g.worldMap.update(g.mapPose(),performance.now(),true);document.getElementById('toast').hidden=true;return {problem,objects:g.objects}}''');check(kind+' upper floor retains normal furniture editing',not edit['problem'],edit);g.screenshot(path=str(OUT/'screenshots'/f'{kind}-{device}-template-upper.png'))
